#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
long long total=0;
for(int i=0;i<n;++i){scanf("%lld",&a[i]);total+=a[i];}
long long left=0;
for(int i=0;i<n;++i){if(left==total-left-a[i]){printf("%d\n",i);return 0;}left+=a[i];}
printf("-1\n");return 0;}

